"""Strict request syntax and normalized full-width addresses, protocol 2."""
import ipaddress
import json
import re

MAX_INPUT = 16 * 1024 * 1024


class Invalid(ValueError):
    pass


def unique_object(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid("duplicate key")
        obj[key] = value
    return obj


def nonfinite(_):
    raise Invalid("nonfinite JSON")


def keys(value, names):
    if type(value) is not dict or set(value) != set(names):
        raise Invalid("object shape")


def array(value):
    if type(value) is not list:
        raise Invalid("array required")
    return value


def integer(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise Invalid("integer range")
    return value


def address(value):
    if (type(value) is not str or not 1 <= len(value) <= 64
            or re.fullmatch(r"[0-9a-fA-F:]+", value) is None):
        raise Invalid("IPv6 address")
    try:
        return int(ipaddress.IPv6Address(value))
    except ValueError as exc:
        raise Invalid("IPv6 address") from exc


def prefix(value):
    if type(value) is not str or len(value) > 64 or value.count("/") != 1:
        raise Invalid("prefix")
    addr, length = value.split("/")
    if re.fullmatch(r"0|[1-9][0-9]*", length) is None:
        raise Invalid("prefix length")
    length = integer(int(length), 0, 128)
    size = 1 << (128 - length)
    return address(addr) // size * size, length


def parse_request(data):
    if len(data) > MAX_INPUT:
        raise Invalid("input byte budget")
    try:
        request = json.loads(data.decode("utf-8"), object_pairs_hook=unique_object,
                             parse_constant=nonfinite)
    except (ValueError, UnicodeError, RecursionError) as exc:
        raise Invalid("JSON") from exc
    keys(request, ["cases"])
    cases = array(request["cases"])
    if len(cases) > 4:
        raise Invalid("case budget")
    rows = version_entries = query_count = burst_count = 0
    normalized = []
    for case in cases:
        keys(case, ["initial", "transactions", "bursts", "cache_pages", "costs"])
        cache = integer(case["cache_pages"], 0, 12)
        costs = case["costs"]
        keys(costs, ["hit", "miss", "decode"])
        hit = integer(costs["hit"], 1, 16)
        miss = integer(costs["miss"], hit, 256)
        dec = array(costs["decode"])
        if len(dec) != 3:
            raise Invalid("decode costs")
        dec = [integer(x, 0, 16) for x in dec]
        initial = array(case["initial"])
        transactions = array(case["transactions"])
        bursts = array(case["bursts"])
        if len(transactions) > 7:
            raise Invalid("version budget")
        rows += len(initial)
        for tx in transactions:
            rows += len(array(tx))
        burst_count += len(bursts)
        if rows > 60000 or burst_count > 256:
            raise Invalid("batch budget")
        routes, init = set(), []
        for row in initial:
            if len(array(row)) != 2:
                raise Invalid("initial row")
            route, hop = prefix(row[0]), integer(row[1], 0, 2147483647)
            init.append((route, hop))
            routes.add(route)
            if len(routes) > 30000:
                raise Invalid("active route budget")
        version_entries += len(routes)
        txs = []
        for tx in transactions:
            out = []
            for change in tx:
                change = array(change)
                if not change or type(change[0]) is not str:
                    raise Invalid("change")
                op = change[0]
                if op == "set" and len(change) == 3:
                    route = prefix(change[1])
                    hop = integer(change[2], 0, 2147483647)
                    routes.add(route)
                    out.append((op, route, hop))
                elif op == "erase" and len(change) == 2:
                    route = prefix(change[1])
                    routes.discard(route)
                    out.append((op, route, None))
                else:
                    raise Invalid("change")
                if len(routes) > 30000:
                    raise Invalid("active route budget")
            txs.append(out)
            version_entries += len(routes)
        if version_entries > 60000:
            raise Invalid("committed route-entry budget")
        queries = []
        for burst in bursts:
            keys(burst, ["version", "repeat", "addresses"])
            version = integer(burst["version"], 0, len(transactions))
            repeat = integer(burst["repeat"], 1, 1000000)
            addresses = array(burst["addresses"])
            query_count += len(addresses)
            if len(addresses) > 64 or query_count > 8192:
                raise Invalid("address budget")
            queries.append((version, repeat, [address(x) for x in addresses]))
        normalized.append({"initial": init, "transactions": txs, "bursts": queries,
                           "cache_pages": cache, "costs": (hit, miss, dec)})
    return normalized

#!/usr/bin/env python3
"""Public sanity checks. The program under test is always a real child."""
import argparse
import json
import os
from pathlib import Path
import resource
import selectors
import signal
import stat
import subprocess
import sys
import time
from audit import audit
from process_guard import (ChildCleanupError, CleanupProfileError,
                           prepare_controller, reap_group, restrict_child)

WALL = 120
STDOUT = 64 * 1024 * 1024
STDERR = 1024 * 1024


def unique(pairs):
    out = {}
    for k, v in pairs:
        if k in out:
            raise ValueError("duplicate output key")
        out[k] = v
    return out


def reject_constant(value):
    raise ValueError("nonfinite JSON")


def decode(data):
    return json.loads(data.decode("utf-8"), object_pairs_hook=unique,
                      parse_constant=reject_constant)


def same(a, b):
    if type(a) is not type(b):
        return False
    if type(a) is dict:
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if type(a) is list:
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b


def child_limits():
    os.setsid()
    for which, values in [
        (resource.RLIMIT_CPU, (180, 181)),
        (resource.RLIMIT_AS, (2 * 1024**3, 2 * 1024**3)),
        (resource.RLIMIT_NOFILE, (256, 256)),
        (resource.RLIMIT_NPROC, (64, 64)),
        (resource.RLIMIT_FSIZE, (64 * 1024**2, 64 * 1024**2)),
        (resource.RLIMIT_CORE, (0, 0)),
        (resource.RLIMIT_STACK, (8 * 1024**2, 8 * 1024**2)),
        (resource.RLIMIT_MEMLOCK, (65536, 65536)),
        (resource.RLIMIT_MSGQUEUE, (819200, 819200)),
        (resource.RLIMIT_SIGPENDING, (4096, 4096)),
        (resource.RLIMIT_NICE, (0, 0)),
        (resource.RLIMIT_RTPRIO, (0, 0)),
    ]:
        resource.setrlimit(which, values)
    restrict_child()


def run_child(entry, data, *, argv=None, raw=False):
    prepare_controller()
    env = dict(os.environ, PYTHONUNBUFFERED="1", PYTHONDONTWRITEBYTECODE="1",
               PYTHONHASHSEED="0", OPENBLAS_NUM_THREADS="1",
               OMP_NUM_THREADS="1", MKL_NUM_THREADS="1", TMPDIR="/workspace/tmp")
    p = subprocess.Popen(argv or [sys.executable, "-B", str(entry)],
                         stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE, env=env, close_fds=True,
                         preexec_fn=child_limits)
    selector = selectors.DefaultSelector()
    output = [bytearray(), bytearray()]
    offset = 0
    deadline = time.monotonic() + WALL
    try:
        for stream in [p.stdin, p.stdout, p.stderr]:
            os.set_blocking(stream.fileno(), False)
        selector.register(p.stdin, selectors.EVENT_WRITE, -1)
        selector.register(p.stdout, selectors.EVENT_READ, 0)
        selector.register(p.stderr, selectors.EVENT_READ, 1)
        while selector.get_map():
            left = deadline - time.monotonic()
            if left <= 0:
                raise ValueError("child wall limit")
            for key, _ in selector.select(min(0.1, left)):
                stream, channel = key.fileobj, key.data
                if channel == -1:
                    if offset == len(data):
                        selector.unregister(stream)
                        stream.close()
                        continue
                    try:
                        offset += os.write(stream.fileno(), data[offset:offset + 65536])
                    except BlockingIOError:
                        pass
