#pragma once
// Scalar packed-image library.
//
// The legacy 64-bit interval/B+ tree code that used to live here could not
// express prefixes above /64 and had no packed representation.  This header
// replaces it with full-width (128 bit) unsigned prefix algebra, the exact
// maximal-forwarding-run compiler, the FIDX v2 image builder and a packed
// lookup kernel that reads the real image bytes.
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <queue>
#include <stdexcept>
#include <string>
#include <vector>

using Key = unsigned __int128;

// Key payload widths and SIMD lane counts per encoding mode.
static const int WIDTH[3] = {16, 8, 4};
static const int LANES[3] = {4, 8, 16};

// The whole address space; 2^128 does not fit in Key so it is carried as a
// separate "top" flag wherever an exclusive upper bound is needed.
struct Bound {
    Key v;
    bool top;
};

inline int cmpBound(const Bound& a, const Bound& b) {
    if (a.top != b.top) return a.top ? 1 : -1;
    if (a.v < b.v) return -1;
    if (a.v > b.v) return 1;
    return 0;
}

inline std::string hexkey(Key x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[unsigned(x & 15)]; x >>= 4; }
    return s;
}

inline Key key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key value = 0;
    for (char c : s) {
        int d = (c >= '0' && c <= '9') ? c - '0' : (c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1;
        if (d < 0) throw std::runtime_error("key digit");
        value = (value << 4) | Key(d);
    }
    return value;
}

// ---------------------------------------------------------------- routes ---

struct Route {
    Key start;
    int length;
    int hop;
};

struct Run {
    Key start;
    int hop;  // -1 means "no matching route"
};

inline Route make_route(const std::string& s, int length, int hop) {
    if (length < 0 || length > 128) throw std::runtime_error("prefix length");
    if (s.size() != 32) throw std::runtime_error("key width");
    Key raw = key(s);
    Key size = (length == 0) ? Key(0) : (Key(1) << (128 - length));
    Route r;
    r.length = length;
    r.hop = hop;
    if (length == 0) {
        r.start = 0;
    } else {
        r.start = (raw >> (128 - length)) << (128 - length);
    }
    (void)size;
    return r;
}

// Maximal forwarding runs of one immutable FIB version: the longest prefix
// match is evaluated on the elementary intervals induced by every route start
// and end, then adjacent equal next hops are coalesced.
inline std::vector<Run> build_runs(const std::vector<Route>& routes) {
    const std::size_t n = routes.size();
    std::vector<Bound> bs(n), be(n);
    for (std::size_t i = 0; i < n; ++i) {
        const Route& r = routes[i];
        if (r.length == 0) {
            bs[i] = Bound{Key(0), false};
            be[i] = Bound{Key(0), true};
        } else {
            Key size = Key(1) << (128 - r.length);
            bs[i] = Bound{r.start, false};
            Key e = r.start + size;
            be[i] = (e < r.start) ? Bound{Key(0), true} : Bound{e, false};
        }
    }
    std::vector<Bound> pts;
    pts.reserve(2 * n + 2);
    pts.push_back(Bound{Key(0), false});
    pts.push_back(Bound{Key(0), true});
    for (std::size_t i = 0; i < n; ++i) { pts.push_back(bs[i]); pts.push_back(be[i]); }
    std::sort(pts.begin(), pts.end(), cmpBound);
    pts.erase(std::unique(pts.begin(), pts.end(),
                           [](const Bound& a, const Bound& b) { return cmpBound(a, b) == 0; }),
              pts.end());

    std::vector<std::size_t> order(n);
    for (std::size_t i = 0; i < n; ++i) order[i] = i;
    std::sort(order.begin(), order.end(),
              [&](std::size_t a, std::size_t b) { return cmpBound(bs[a], bs[b]) < 0; });

    std::priority_queue<std::pair<int, std::size_t> > heap;  // longest prefix first
    std::size_t ri = 0;
    std::vector<Run> runs;
    for (std::size_t p = 0; p + 1 < pts.size(); ++p) {
        while (ri < n && cmpBound(bs[order[ri]], pts[p]) <= 0) {
            heap.push(std::make_pair(routes[order[ri]].length, order[ri]));
            ++ri;
        }
        while (!heap.empty() && cmpBound(be[heap.top().second], pts[p]) <= 0) heap.pop();
        int hop = heap.empty() ? -1 : routes[heap.top().second].hop;
        if (!runs.empty() && runs.back().hop == hop) continue;
        Run r;
        r.start = pts[p].v;
        r.hop = hop;
        runs.push_back(r);
    }
    return runs;
}

