    used += std::size_t(keys) * std::size_t(WIDTH[mode]);
    return int(((used + 63) / 64) * 64);
}

inline void put16(unsigned char* p, unsigned v) {
    p[0] = (unsigned char)(v & 0xff);
    p[1] = (unsigned char)((v >> 8) & 0xff);
}

inline void put32(unsigned char* p, std::uint32_t v) {
    for (int i = 0; i < 4; ++i) p[i] = (unsigned char)((v >> (8 * i)) & 0xff);
}

inline void put64(unsigned char* p, std::uint64_t v) {
    for (int i = 0; i < 8; ++i) p[i] = (unsigned char)((v >> (8 * i)) & 0xff);
}

inline void put128(unsigned char* p, Key v) {
    for (int i = 0; i < 16; ++i) p[i] = (unsigned char)((v >> (8 * i)) & 0xff);
}

inline unsigned get16(const unsigned char* p) {
    return unsigned(p[0]) | (unsigned(p[1]) << 8);
}

inline std::uint32_t get32(const unsigned char* p) {
    std::uint32_t v = 0;
    for (int i = 0; i < 4; ++i) v |= std::uint32_t(p[i]) << (8 * i);
    return v;
}

inline std::uint64_t get64(const unsigned char* p) {
    std::uint64_t v = 0;
    for (int i = 0; i < 8; ++i) v |= std::uint64_t(p[i]) << (8 * i);
    return v;
}

inline Key get128(const unsigned char* p) {
    Key v = 0;
    for (int i = 15; i >= 0; --i) v = (v << 8) | Key(p[i]);
    return v;
}

inline bool mode_legal(int mode, Key base, Key top) {
    if (mode == 0) return true;
    Key spread = top - base;
    if (mode == 1) return spread < (Key(1) << 64);
    return spread < (Key(1) << 32);
}

inline std::string to_hex(const std::vector<unsigned char>& buf) {
    static const char* d = "0123456789abcdef";
    std::string s;
    s.reserve(buf.size() * 2);
    for (std::size_t i = 0; i < buf.size(); ++i) {
        s.push_back(d[buf[i] >> 4]);
        s.push_back(d[buf[i] & 15]);
    }
    return s;
}

// Decoded image: nodes indexed by their byte offset / 64.
struct PNode {
    int kind, mode, cached, lo, span;
    std::uint32_t off;
    std::vector<std::uint32_t> children;
    std::vector<Key> keys;
};

struct PImage {
    int runs;
    std::vector<PNode> nodes;
    std::vector<int> hops;
    std::vector<int> byoff;
};

inline PImage decode_image(const unsigned char* raw, std::size_t len) {
    if (len < 128 || len % 64) throw std::runtime_error("image size");
    if (std::memcmp(raw, "FIDX", 4) != 0) throw std::runtime_error("image magic");
    if (raw[4] != 2) throw std::runtime_error("image version");
    for (int i = 5; i < 8; ++i) if (raw[i]) throw std::runtime_error("image header");
    std::uint32_t runs = get32(raw + 8);
    std::uint32_t nodes = get32(raw + 12);
    std::uint32_t hopoff = get32(raw + 16);
    std::uint32_t total = get32(raw + 20);
    if (total != len) throw std::runtime_error("image length");
    for (int i = 24; i < 64; ++i) if (raw[i]) throw std::runtime_error("image header");
    if (hopoff % 64 || hopoff > len) throw std::runtime_error("image hop offset");
    if (runs == 0 || nodes == 0) throw std::runtime_error("image empty");
    PImage img;
    img.runs = int(runs);
    img.byoff.assign(len / 64, -1);
    for (std::uint32_t i = 0; i < runs; ++i) {
        std::uint32_t v = get32(raw + hopoff + 4 * i);
        img.hops.push_back(v == 0xffffffffu ? -1 : int(v));
    }
    std::uint32_t off = 64;
    for (std::uint32_t i = 0; i < nodes; ++i) {
        if (off + 32 > hopoff) throw std::runtime_error("image node");
        PNode n;
        n.off = off;
        n.kind = raw[off];
        n.mode = raw[off + 1];
        n.cached = raw[off + 2];
        n.lo = int(get16(raw + off + 4));
        n.span = int(get16(raw + off + 6));
        int count = int(get16(raw + off + 8));
        std::uint32_t alloc = get32(raw + off + 12);
        if (raw[off + 3] || get16(raw + off + 10)) throw std::runtime_error("image node tag");
        if (n.kind == 0) {
            if (count < 2 || count > 9) throw std::runtime_error("image arity");
            const unsigned char* q = raw + off + 32;
            for (int c = 0; c < count; ++c) n.children.push_back(get32(q + 4 * c));
            q += 4 * count;
            Key base = get128(raw + off + 16);
            for (int c = 0; c + 1 < count; ++c) {
                Key k;
                if (n.mode == 0) k = get128(q);
                else if (n.mode == 1) k = base + Key(get64(q));
                else k = base + Key(get32(q));
                n.keys.push_back(k);
                q += WIDTH[n.mode];
            }
            if (alloc != std::uint32_t(alloc_bytes(true, count, n.mode)))
                throw std::runtime_error("image allocation");
        } else if (n.kind == 1) {
            if (count != n.span || n.span < 1 || n.span > 8)
                throw std::runtime_error("image leaf");
            const unsigned char* q = raw + off + 32;
            Key base = get128(raw + off + 16);
            for (int c = 0; c < n.span; ++c) {
                Key k;
                if (n.mode == 0) k = get128(q);
                else if (n.mode == 1) k = base + Key(get64(q));
                else k = base + Key(get32(q));
                n.keys.push_back(k);
                q += WIDTH[n.mode];
            }
            if (alloc != std::uint32_t(alloc_bytes(false, n.span, n.mode)))
                throw std::runtime_error("image allocation");
        } else {
            throw std::runtime_error("image node kind");
        }
        img.byoff[off / 64] = int(img.nodes.size());
        img.nodes.push_back(n);
        off += alloc;
    }
    if (off != hopoff) throw std::runtime_error("image node area");
    return img;
}

inline Answer lookup_image(const PImage& img, Key addr) {
    Answer a;
    a.hop = -1;
    a.run = -1;
    std::uint32_t off = 64;
    for (;;) {
        a.path.push_back(off);
        int idx = img.byoff[off / 64];
        if (idx < 0) throw std::runtime_error("image offset");
        const PNode& n = img.nodes[idx];
        std::size_t c = 0;
        while (c < n.keys.size() && n.keys[c] <= addr) ++c;
        if (n.kind == 1) {
            if (c == 0) throw std::runtime_error("image predecessor");
            a.run = n.lo + int(c) - 1;
            if (a.run < 0 || a.run >= img.runs) throw std::runtime_error("image run");
            a.hop = img.hops[a.run];
            break;
        }
        if (c >= n.children.size()) throw std::runtime_error("image child");
        off = n.children[c];
    }
    return a;
}

// Build the exact FIDX v2 byte image for a supplied layout (nodes are given in
// breadth-first order) and answer the requested addresses with the packed
// lookup kernel.
inline PackedResult pack_image(const std::vector<Key>& starts, const std::vector<int>& hops,
                               const std::vector<Layout>& nodes, const std::vector<Key>& addresses) {
    const std::size_t R = starts.size();
    if (R == 0) throw std::runtime_error("empty run set");
    if (nodes.empty()) throw std::runtime_error("empty layout");
    std::vector<std::uint32_t> off(nodes.size());
    std::uint32_t cur = 64;
    for (std::size_t i = 0; i < nodes.size(); ++i) {
        const Layout& n = nodes[i];
        int b = int(n.children.size());
        bool internal = b > 0;
        if (internal && (b < 2 || b > 9)) throw std::runtime_error("arity");
        if (!internal && (n.span < 1 || n.span > 8)) throw std::runtime_error("leaf span");
        if (n.lo < 0 || n.span < 1 || n.lo + n.span > int(R)) throw std::runtime_error("node range");
        if (n.mode < 0 || n.mode > 2) throw std::runtime_error("node mode");
        off[i] = cur;
        cur += std::uint32_t(alloc_bytes(internal, internal ? b : n.span, n.mode));
    }
    std::uint32_t hopoff = cur;
    std::size_t hopbytes = ((R * 4 + 63) / 64) * 64;
    std::size_t total = std::size_t(hopoff) + hopbytes;
    std::vector<unsigned char> buf(total, 0);
    std::memcpy(buf.data(), "FIDX", 4);
    buf[4] = 2;
    put32(buf.data() + 8, std::uint32_t(R));
    put32(buf.data() + 12, std::uint32_t(nodes.size()));
    put32(buf.data() + 16, hopoff);
    put32(buf.data() + 20, std::uint32_t(total));
    for (std::size_t i = 0; i < nodes.size(); ++i) {
        const Layout& n = nodes[i];
        int b = int(n.children.size());
        bool internal = b > 0;
        Key base = starts[n.lo];
        Key top = starts[n.lo + n.span - 1];
        if (!mode_legal(n.mode, base, top)) throw std::runtime_error("mode range");
        unsigned char* p = buf.data() + off[i];
        p[0] = internal ? 0 : 1;
        p[1] = (unsigned char)n.mode;
        p[2] = (unsigned char)(n.cached ? 1 : 0);
        p[3] = 0;
        put16(p + 4, (unsigned)n.lo);
        put16(p + 6, (unsigned)n.span);
        put16(p + 8, (unsigned)(internal ? b : n.span));
        put16(p + 10, 0);
        put32(p + 12, std::uint32_t(alloc_bytes(internal, internal ? b : n.span, n.mode)));
        put128(p + 16, base);
        unsigned char* q = p + 32;
        if (internal) {
            for (int c = 0; c < b; ++c) put32(q + 4 * c, off[n.children[c]]);
            q += 4 * b;
            for (int c = 1; c < b; ++c) {
                Key k = starts[nodes[n.children[c]].lo];
                if (n.mode == 0) {
                    put128(q, k);
                } else if (n.mode == 1) {
                    put64(q, (std::uint64_t)(k - base));
                } else {
                    put32(q, (std::uint32_t)(k - base));
                }
                q += WIDTH[n.mode];
            }
        } else {
            for (int c = 0; c < n.span; ++c) {
                Key k = starts[n.lo + c];
                if (n.mode == 0) {
                    put128(q, k);
                } else if (n.mode == 1) {
                    put64(q, (std::uint64_t)(k - base));
                } else {
                    put32(q, (std::uint32_t)(k - base));
                }
                q += WIDTH[n.mode];
            }
        }
    }
    for (std::size_t i = 0; i < R; ++i) {
        std::uint32_t v = (hops[i] < 0) ? 0xffffffffu : std::uint32_t(hops[i]);
        put32(buf.data() + hopoff + 4 * i, v);
    }
    PackedResult result;
    result.image = to_hex(buf);
    PImage img = decode_image(buf.data(), buf.size());
    for (std::size_t i = 0; i < addresses.size(); ++i)
        result.answers.push_back(lookup_image(img, addresses[i]));
    return result;
}

// Look up addresses in an existing image; the image bytes are the only source
// of keys, children and hops.
inline std::vector<Answer> trace_image(const std::string& image, const std::vector<Key>& addresses) {
    if (image.size() % 2) throw std::runtime_error("image hex");
    std::vector<unsigned char> raw(image.size() / 2);
    for (std::size_t i = 0; i < raw.size(); ++i) {
        int hi = image[2 * i], lo = image[2 * i + 1];
        int hv = (hi >= '0' && hi <= '9') ? hi - '0' : (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 : -1;
        int lv = (lo >= '0' && lo <= '9') ? lo - '0' : (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 : -1;
        if (hv < 0 || lv < 0) throw std::runtime_error("image hex");
        raw[i] = (unsigned char)((hv << 4) | lv);
    }
    PImage img = decode_image(raw.data(), raw.size());
    std::vector<Answer> out;
    for (std::size_t i = 0; i < addresses.size(); ++i)
        out.push_back(lookup_image(img, addresses[i]));
    return out;
}
