#pragma once
// Exact planner for the packed forwarding images.
//
// For one immutable FIB version the canonical runs form an ordered sequence.
// A legal image is an ordered tree over those runs: a leaf covers 1..8
// consecutive runs, an internal node has 2..9 children that partition the
// parent's run range, and every node picks one of three key encodings plus an
// optional resident (cached) flag.
//
// The work of a node covering runs [i,j) is
//
//   P * (hit if cached else miss) * T(i,j) + (ceil(K/lanes) + decode) * Q(i,j)
//
// with Q the weighted number of burst addresses inside the node and T the
// weighted number of bursts that touch it.  Because P depends on the arity
// and the encoding, and because the resident pages are shared by every
// version of a case, tree shape, encoding and residency are optimised
// jointly by an interval dynamic program:
//
//   F(i,j,c)  = best (work, pages) of the subtree rooted at a node that covers
//               runs [i,j) when at most c resident pages may be used inside it
//   S_k(i,j,c)= best (work, pages) of a sequence of exactly k subtrees that
//               partition runs [i,j) using at most c resident pages
//
// F is solved in increasing span order; S_k is the standard segmentation
// recurrence over the split point.  Both are compared lexicographically so
// that work is minimised first and image pages second.
#include "engine.hpp"

#include <limits>
#include <utility>

namespace planner {

static const long long INF = (long long)1 << 62;

struct Version {
    int runs = 0;
    std::vector<Key> starts;
    std::vector<int> hops;
    std::vector<int> rep;                   // burst repeat counts
    std::vector<std::vector<Key> > addrs;   // burst addresses
};

struct Node {
    int lo, span, mode, cached;
    std::vector<int> children;
};

struct Result {
    long long work = 0;
    long long pages = 0;
    std::vector<std::vector<Node> > versions;
};

struct Tables {
    int R = 0, B = 0;
    std::vector<long long> Fw;
    std::vector<int> Fp;
    std::vector<std::uint8_t> Fmode, Fcach, Fkind;  // kind 0 = leaf, else arity
    std::vector<std::vector<long long> > Sw;         // k = 2..9
    std::vector<std::vector<int> > Sp;
    std::vector<std::vector<std::uint16_t> > St;
    std::vector<std::vector<std::uint8_t> > Sc;

    std::size_t idx(int i, int j, int c) const {
        return (std::size_t(i) * std::size_t(R + 1) + std::size_t(j)) * std::size_t(B + 1) +
               std::size_t(c);
    }
};

struct Planner {
    int hit, miss;
    int decode[3];
    Tables T;

    Planner(int h, int m, const int dec[3]) : hit(h), miss(m) {
        decode[0] = dec[0];
        decode[1] = dec[1];
        decode[2] = dec[2];
    }

    void solve(const Version& ver, int budget) {
        T.R = ver.runs;
        T.B = budget;
        std::vector<long long> Q, Tt;
        build_weights(ver, Q, Tt);
        fill(ver, Q, Tt);
    }

    void build_weights(const Version& ver, std::vector<long long>& Q, std::vector<long long>& Tt) {
        const int R = T.R;
        const std::size_t side = std::size_t(R + 1) * std::size_t(R + 1);
        Q.assign(side, 0);
        Tt.assign(side, 0);
        std::vector<std::vector<int> > pre;
        pre.reserve(ver.rep.size());
        for (std::size_t b = 0; b < ver.rep.size(); ++b) {
            std::vector<int> p(std::size_t(R) + 1, 0);
            for (std::size_t a = 0; a < ver.addrs[b].size(); ++a) {
                int r = int(std::upper_bound(ver.starts.begin(), ver.starts.end(), ver.addrs[b][a]) -
                            ver.starts.begin()) - 1;
                if (r < 0) r = 0;
                if (r > R - 1) r = R - 1;
                p[std::size_t(r) + 1] += 1;
            }
            for (int r = 0; r < R; ++r) p[std::size_t(r) + 1] += p[std::size_t(r)];
            pre.push_back(p);
        }
        for (int i = 0; i <= R; ++i) {
            for (int j = i + 1; j <= R; ++j) {
                long long q = 0, t = 0;
                for (std::size_t b = 0; b < pre.size(); ++b) {
                    long long n = pre[b][std::size_t(j)] - pre[b][std::size_t(i)];
                    q += (long long)ver.rep[b] * n;
                    if (n > 0) t += ver.rep[b];
                }
                Q[std::size_t(i) * std::size_t(R + 1) + std::size_t(j)] = q;
                Tt[std::size_t(i) * std::size_t(R + 1) + std::size_t(j)] = t;
            }
        }
    }

    void fill(const Version& ver, const std::vector<long long>& Q, const std::vector<long long>& Tt) {
        const int R = T.R, B = T.B;
        const std::size_t side = std::size_t(R + 1) * std::size_t(R + 1);
        const std::size_t N = side * std::size_t(B + 1);
        T.Fw.assign(N, INF);
        T.Fp.assign(N, 0);
        T.Fmode.assign(N, 0);
        T.Fcach.assign(N, 0);
        T.Fkind.assign(N, 0);
        T.Sw.assign(8, std::vector<long long>(N, INF));
        T.Sp.assign(8, std::vector<int>(N, 0));
        T.St.assign(8, std::vector<std::uint16_t>(N, 0));
        T.Sc.assign(8, std::vector<std::uint8_t>(N, 0));

        for (int span = 1; span <= R; ++span) {
            for (int i = 0; i + span <= R; ++i) {
                int j = i + span;
                const Key base = ver.starts[i];
                const Key top = ver.starts[j - 1];
                const long long qij = Q[std::size_t(i) * std::size_t(R + 1) + std::size_t(j)];
                const long long tij = Tt[std::size_t(i) * std::size_t(R + 1) + std::size_t(j)];
                // Sequences of exactly k subtrees covering [i,j).
                for (int k = 2; k <= 9; ++k) {
                    if (k > span) continue;
                    std::vector<long long>& sw = T.Sw[k - 2];
                    std::vector<int>& sp = T.Sp[k - 2];
                    std::vector<std::uint16_t>& st = T.St[k - 2];
                    std::vector<std::uint8_t>& sc = T.Sc[k - 2];
                    const std::vector<long long>& pw = (k == 2) ? T.Fw : T.Sw[k - 3];
                    const std::vector<int>& pp = (k == 2) ? T.Fp : T.Sp[k - 3];
                    for (int c = 0; c <= B; ++c) {
                        long long bw = INF;
                        int bp = 0;
                        std::uint16_t bt = 0;
                        std::uint8_t bc = 0;
                        for (int t = i + 1; t < j; ++t) {
                            std::size_t bit = T.idx(i, t, 0);
                            std::size_t bit2 = T.idx(t, j, 0);
                            for (int c1 = 0; c1 <= c; ++c1) {
                                long long a = pw[bit + std::size_t(c1)];
                                if (a >= INF) continue;
                                long long b = T.Fw[bit2 + std::size_t(c - c1)];
                                if (b >= INF) continue;
                                long long cw = a + b;
                                int cp = pp[bit + std::size_t(c1)] + T.Fp[bit2 + std::size_t(c - c1)];
                                if (cw < bw || (cw == bw && cp < bp)) {
                                    bw = cw;
                                    bp = cp;
                                    bt = (std::uint16_t)t;
                                    bc = (std::uint8_t)c1;
                                }
                            }
                        }
                        std::size_t si = T.idx(i, j, c);
                        sw[si] = bw;
                        sp[si] = bp;
                        st[si] = bt;
                        sc[si] = bc;
                    }
                }
                // The node itself.
                for (int c = 0; c <= B; ++c) {
                    long long bw = INF;
                    int bp = 0;
                    std::uint8_t bm = 0, bcach = 0, bkind = 0;
                    if (span <= 8) {
                        for (int m = 0; m < 3; ++m) {
                            if (!mode_legal(m, base, top)) continue;
                            int P = alloc_bytes(false, span, m) / 64;
                            long long per = (span + LANES[m] - 1) / LANES[m] + decode[m];
                            for (int f = 0; f < 2; ++f) {
                                if (f && P > c) continue;
                                long long w = (long long)P * (f ? hit : miss) * tij + per * qij;
                                if (w < bw || (w == bw && P < bp)) {
                                    bw = w;
                                    bp = P;
                                    bm = (std::uint8_t)m;
                                    bcach = (std::uint8_t)f;
                                    bkind = 0;
                                }
                            }
                        }
                    }
                    for (int k = 2; k <= 9 && k <= span; ++k) {
                        const std::vector<long long>& sw = T.Sw[k - 2];
                        const std::vector<int>& sp = T.Sp[k - 2];
                        for (int m = 0; m < 3; ++m) {
                            if (!mode_legal(m, base, top)) continue;
                            int P = alloc_bytes(true, k, m) / 64;
                            long long per = (k - 1 + LANES[m] - 1) / LANES[m] + decode[m];
                            for (int f = 0; f < 2; ++f) {
                                int c2 = c - (f ? P : 0);
                                if (c2 < 0) continue;
                                std::size_t si = T.idx(i, j, c2);
                                long long s = sw[si];
                                if (s >= INF) continue;
                                long long w = s + (long long)P * (f ? hit : miss) * tij + per * qij;
                                int pg = sp[si] + P;
                                if (w < bw || (w == bw && pg < bp)) {
                                    bw = w;
                                    bp = pg;
                                    bm = (std::uint8_t)m;
                                    bcach = (std::uint8_t)f;
                                    bkind = (std::uint8_t)k;
                                }
                            }
                        }
                    }
                    std::size_t fi = T.idx(i, j, c);
                    T.Fw[fi] = bw;
                    T.Fp[fi] = bp;
                    T.Fmode[fi] = bm;
                    T.Fcach[fi] = bcach;
                    T.Fkind[fi] = bkind;
                }
            }
        }
    }

    int build(int i, int j, int c, std::vector<Node>& nodes) {
        std::size_t fi = T.idx(i, j, c);
        Node n;
        n.lo = i;
        n.span = j - i;
        n.mode = T.Fmode[fi];
        n.cached = T.Fcach[fi];
        int kind = T.Fkind[fi];
        int id = (int)nodes.size();
        nodes.push_back(n);
        if (kind == 0) return id;
        int P = alloc_bytes(true, kind, n.mode) / 64;
        int c2 = c - (n.cached ? P : 0);
        std::vector<int> kids;
        build_seq(kind, i, j, c2, nodes, kids);
        nodes[id].children = kids;
        return id;
    }

    void build_seq(int k, int i, int j, int c, std::vector<Node>& nodes, std::vector<int>& out) {
        if (k == 1) {
            out.push_back(build(i, j, c, nodes));
            return;
        }
        std::size_t si = T.idx(i, j, c);
        int t = T.St[k - 2][si];
        int c1 = T.Sc[k - 2][si];
        build_seq(k - 1, i, t, c1, nodes, out);
        out.push_back(build(t, j, c - c1, nodes));
    }

    // Returns the layout of one version in breadth-first order.
    std::vector<Node> layout(int budget) {
        std::vector<Node> nodes;
        build(0, T.R, budget, nodes);
        std::vector<int> order, remap(nodes.size(), -1);
        order.push_back(0);
        remap[0] = 0;
        for (std::size_t q = 0; q < order.size(); ++q) {
            int id = order[q];
            for (std::size_t c = 0; c < nodes[id].children.size(); ++c) {
                int ch = nodes[id].children[c];
                remap[ch] = (int)order.size();
                order.push_back(ch);
            }
        }
        std::vector<Node> out;
        out.reserve(order.size());
        for (std::size_t q = 0; q < order.size(); ++q) {
            Node n = nodes[order[q]];
            for (std::size_t c = 0; c < n.children.size(); ++c)
                n.children[c] = remap[n.children[c]];
            out.push_back(n);
        }
        return out;
    }
};

// Optimise one case: every version of the case shares the resident page
// budget, so the per-version tables are combined with a knapsack over the
// budget before the layouts are rebuilt.
inline Result solve_case(const std::vector<Version>& versions, int cache_pages, int hit, int miss,
                          const int decode[3]) {
    Result result;
    std::vector<Planner> plans;
    plans.reserve(versions.size());
    for (std::size_t v = 0; v < versions.size(); ++v) {
        plans.push_back(Planner(hit, miss, decode));
        plans.back().solve(versions[v], cache_pages);
    }
    std::vector<std::vector<std::pair<long long, int> > > G(versions.size());
    for (std::size_t v = 0; v < versions.size(); ++v) {
        G[v].resize(std::size_t(cache_pages) + 1);
        for (int c = 0; c <= cache_pages; ++c) {
            std::size_t fi = plans[v].T.idx(0, versions[v].runs, c);
            G[v][std::size_t(c)] = std::make_pair(plans[v].T.Fw[fi], plans[v].T.Fp[fi]);
        }
    }
    std::vector<std::pair<long long, int> > best(std::size_t(cache_pages) + 1,
                                                 std::make_pair(0LL, 0));
    std::vector<std::vector<int> > split(versions.size(),
                                         std::vector<int>(std::size_t(cache_pages) + 1, 0));
    for (std::size_t v = 0; v < versions.size(); ++v) {
        std::vector<std::pair<long long, int> > next(std::size_t(cache_pages) + 1,
                                                     std::make_pair(INF, 0));
        for (int c = 0; c <= cache_pages; ++c) {
            for (int c1 = 0; c1 <= c; ++c1) {
                long long w = best[std::size_t(c1)].first + G[v][std::size_t(c - c1)].first;
                int p = best[std::size_t(c1)].second + G[v][std::size_t(c - c1)].second;
                if (w < next[std::size_t(c)].first ||
                    (w == next[std::size_t(c)].first && p < next[std::size_t(c)].second)) {
                    next[std::size_t(c)] = std::make_pair(w, p);
                    split[v][std::size_t(c)] = c1;
                }
            }
        }
        best = next;
    }
    std::vector<int> alloc(versions.size(), 0);
    int cur = cache_pages;
    for (int v = (int)versions.size() - 1; v >= 0; --v) {
        int prev = split[std::size_t(v)][std::size_t(cur)];
        alloc[std::size_t(v)] = cur - prev;
        cur = prev;
    }
    for (std::size_t v = 0; v < versions.size(); ++v) {
        result.versions.push_back(plans[v].layout(alloc[v]));
        result.work += G[v][std::size_t(alloc[v])].first;
        result.pages += G[v][std::size_t(alloc[v])].second;
        // Header page and the padded hop array of this version.
        result.pages += 1 + (versions[v].runs * 4 + 63) / 64;
    }
    return result;
}

}  // namespace planner
