def bound_hex(value):
    if value == UNIVERSE:
        return '1' + '0' * 32
    return '%032x' % value


def compute_changes(old_starts, old_hops, new_starts, new_hops):
    """Forwarding differences between two consecutive versions."""
    points = sorted(set(old_starts) | set(new_starts))
    rows = []
    for index in range(len(points) - 1):
        low = points[index]
        high = points[index + 1]
        old = old_hops[bisect_right(old_starts, low) - 1]
        new = new_hops[bisect_right(new_starts, low) - 1]
        if old == new:
            continue
        if rows and rows[-1][1] == low and rows[-1][2] == old and rows[-1][3] == new:
            rows[-1][1] = high
        else:
            rows.append([low, high, old, new])
    return rows


def build_tree(nodes):
    """Rebuild the nested tree of one version from its breadth-first nodes."""
    objects = []
    for node in nodes:
        objects.append({'lo': node['lo'], 'span': node['span'], 'mode': node['mode'],
                        'cached': node['cached'], 'children': []})
    for index, node in enumerate(nodes):
        for child in node['children']:
            objects[index]['children'].append(objects[child])
    return objects[0]


def validate_layout(nodes, starts):
    """Check that a planned layout is a legal tree over the canonical runs."""
    runs = len(starts)
    if not nodes:
        return False
    seen = [False] * len(nodes)

    def check(index, low, high):
        if index < 0 or index >= len(nodes) or seen[index]:
            return False
        seen[index] = True
        node = nodes[index]
        if node['lo'] != low or node['span'] != high - low:
            return False
        if node['mode'] not in (0, 1, 2):
            return False
        spread = starts[high - 1] - starts[low]
        if node['mode'] == 1 and spread >= (1 << 64):
            return False
        if node['mode'] == 2 and spread >= (1 << 32):
            return False
        kids = node['children']
        if not kids:
            return 1 <= high - low <= 8
        if not 2 <= len(kids) <= 9:
            return False
        cursor = low
        for kid in kids:
            if kid < 0 or kid >= len(nodes):
                return False
            span = nodes[kid]['span']
            if nodes[kid]['lo'] != cursor:
                return False
            if not check(kid, cursor, cursor + span):
                return False
            cursor += span
        return cursor == high

    if not check(0, 0, runs):
        return False
    return all(seen)


# --------------------------------------------------------------- fallback ---

def _weights(version):
    """Q and T of every run range of one version."""
    starts = version['starts']
    runs = len(starts)
    prefix = []
    for repeat, addresses in version['bursts']:
        counts = [0] * (runs + 1)
        for address in addresses:
            run = bisect_right(starts, address) - 1
            if run < 0:
                run = 0
            elif run > runs - 1:
                run = runs - 1
            counts[run + 1] += 1
        for run in range(runs):
            counts[run + 1] += counts[run]
        prefix.append((repeat, counts))
    weights = {}
    for low in range(runs):
        for high in range(low + 1, runs + 1):
            q = 0
            t = 0
            for repeat, counts in prefix:
                hits = counts[high] - counts[low]
                q += repeat * hits
                if hits:
                    t += repeat
            weights[(low, high)] = (q, t)
    return weights


def _simple_tree(runs):
    """A plain legal tree: leaves of at most eight runs, arity at most nine."""
    nodes = []

    def build(low, high):
        span = high - low
        if span <= 8:
            index = len(nodes)
            nodes.append([low, span, []])
            return index
        count = min(9, max(2, (span + 7) // 8))
        base = span // count
        extra = span % count
        index = len(nodes)
        nodes.append([low, span, []])
        position = low
        for step in range(count):
            size = base + (1 if step < extra else 0)
            nodes[index][2].append(build(position, position + size))
            position += size

